async function api(action:string,args:any){
  const r=await fetch("actions",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action,args})});
  const j=await r.json(); if(!r.ok||j.error) throw new Error(j.error||('Request failed: '+r.status)); return j.data;
}
function fmt(n:number){return 'EGP '+n.toLocaleString('en-US')}
function Badge({children,color='bg-blue-100 text-blue-700'}:{children:any;color?:string}){return <span className={`chip ${color}`}>{children}</span>}
function SectionTitle({title,sub}:{title:string;sub?:string}){return <div className="mb-3"><h2 className="text-lg font-extrabold tracking-tight">{title}</h2>{sub&&<p className="text-xs" style={{color:'var(--muted)'}}>{sub}</p>}</div>}
function Stat({label,value,sub,icon,color}:{label:string;value:string;sub:string;icon:any;color:string}){return <div className="card p-4 fade-up"><div className="flex justify-between items-start"><div><p className="text-[11px] font-bold uppercase tracking-wider" style={{color:'var(--muted)'}}>{label}</p><div className="kpi-num mt-1">{value}</div><p className="text-[11px] mt-1" style={{color:'var(--muted)'}}>{sub}</p></div><div className="w-10 h-10 rounded-xl flex items-center justify-center text-white shrink-0" style={{background:color}}>{icon}</div></div></div>}

