  const [cart,setCart]=useState<{id:string;qty:number}[]>([]); const [discount,setDiscount]=useState(0); const [payMethod,setPayMethod]=useState('Cash'); const [posCat,setPosCat]=useState('All'); const [posQuery,setPosQuery]=useState(''); const [receipt,setReceipt]=useState<any>(null);
