  const [progCoach,setProgCoach]=useState('Ahmed El-Sayed'); const [savedPrograms,setSavedPrograms]=useState<string[]>(['Push / Pull / Legs — Omar Hassan','Weight Loss — Sara Ahmed','Beginner Full Body — Heba Samir']);
  const [invForm,setInvForm]=useState({member:'Omar Hassan',amount:'550',plan:'Monthly'}); const [water,setWater]=useState(2.1);
