  // Load durable members saved through records API
  useEffect(()=>{ (async()=>{ try{ const data:any=await api("records.list",{collection:"gympro_members"}); if(data?.records?.length){ const saved=data.records.map((r:any)=>r.value).filter((v:any)=>v&&v.code&&!initialMembers.some(m=>m.code===v.code)); if(saved.length) setMembers(prev=>[...prev,...saved]); } }catch{} })(); },[]);
  function notify(msg:string,kind='ok'){setToast(msg); setToastKind(kind)}
  async function createRow(row:any){ return api("records.create",{collection:"gympro_members",value:row,idempotency_key:'member-'+row.code}); }
  async function reloadRecords(){ const data:any=await api("records.list",{collection:"gympro_members"}); if(data?.records?.length){ const saved=data.records.map((r:any)=>r.value).filter((v:any)=>v&&v.code); const merged=[...initialMembers]; saved.forEach((v:any)=>{ if(!merged.some(m=>m.code===v.code)) merged.push(v); }); setMembers(merged);} }
  async function handleAddMember(e:any){ e.preventDefault(); if(!form.name.trim()||form.phone.trim().length<7){setFormErr(lang==='ar'?'أدخل اسماً ورقم هاتف صحيحاً':'Enter a valid name and phone number'); return} setFormErr(''); const code='M-'+(1050+members.length+1); const row:Member={id:'m'+Date.now(),code,name:form.name,ar:form.ar||form.name,phone:form.phone,branch:form.branch,plan:form.plan,coach:form.coach,status:'Active',join:new Date().toISOString().slice(0,10),expiry:'2026-12-31',balance:0,visits:0,weight:75,email:form.email,emergency:form.emergency}; try{ await createRow(row); await reloadRecords(); }catch(err){ /* API unavailable in preview — keep local save */ setMembers(prev=>[row,...prev]); }
    setMembers(prev=>prev.some(m=>m.code===row.code)?prev:[row,...prev]); const amt=form.plan==='Monthly'?550:form.plan==='Quarterly'?1450:form.plan==='Annual'?4800:9500; setInvoices(prev=>[{id:'INV-2026-'+(1050+prev.length),member:row.name,amount:amt,plan:row.plan,status:'Paid',date:new Date().toISOString().slice(0,10),method:'Cash'},...prev]); setJournal(prev=>[{id:'JE-'+(100+prev.length),date:new Date().toISOString().slice(0,10),desc:`Membership — ${row.name} (${row.plan})`,debit:`1100 Cash ${amt.toLocaleString()}`,credit:`4100 Membership Revenue ${amt.toLocaleString()}`,amount:amt},...prev]); setShowAddMember(false); setForm({name:'',ar:'',phone:'',email:'',plan:'Monthly',coach:'Ahmed El-Sayed',branch:'Nasr City HQ',emergency:''}); setView('members'); notify(t('memberAdded')); }
