  const cartLines=cart.map(c=>({...products.find(p=>p.id===c.id)!,qty:c.qty})).filter(x=>x.id);
  const subtotal=cartLines.reduce((s,x)=>s+x.sell*x.qty,0); const vat=Math.round((subtotal-discount)*0.14); const grand=subtotal-discount+vat;
